root=Path(__file__).resolve().parents[1]
for path in (root/'src').glob('Localization*.cs'):
    text=path.read_text(encoding='utf-8-sig')
    if path.name=='Localization.Polish.cs':
        for k,v in zip(keys,rows['Pl'].split('|')):
            if re.search(r'(?:^|(?<=@"))'+k+r'\|',text,re.M):text=re.sub(r'(?:^|(?<=@"))'+k+r'\|[^\n]*',k+'|'+v,text,flags=re.M)
            else:text=text.replace('const string PolishUi = @"','const string PolishUi = @"'+k+'|'+v+'\n')
    else:
        pattern=r'(Dictionary<string,\s*string> Strings(\w+) = new Dictionary<string,\s*string>\([^\n]+\) \{)(.*?)(\n\s*};)'
        def update(m):
            body=m[3]
            for k,v in zip(keys,rows[m[2]].split('|')):
                entry='            { '+json.dumps(k)+', '+json.dumps(v,ensure_ascii=False)+' },'
                regex=r'^[ \t]*\{ "'+k+r'", [^\n]*\},'
                if re.search(regex,body,re.M):body=re.sub(regex,lambda _:entry,body,flags=re.M)
                else:body='\n'+entry+body
            return m[1]+body+m[4]
        text=re.sub(pattern,update,text,flags=re.S)
    path.write_text(text,encoding='utf-8-sig',newline='\r\n')
